INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$ماذا أفعل إذا انتهت صلاحية الكملك (الحماية المؤقتة)؟$$)::uuid, $$ماذا أفعل إذا انتهت صلاحية الكملك (الحماية المؤقتة)؟$$, $$الكملك والحماية المؤقتة$$, $$الكملك (بطاقة الحماية المؤقتة) لا "يسقط" فوراً بانتهاء التاريخ المطبوع عليه، لكن يجب مراجعة إدارة الهجرة (Göç İdaresi) لتحديث بياناتك وتجديد الوثيقة في أقرب وقت لتجنّب تجميد القيد. جهّز الجواز أو الوثيقة القديمة، إثبات العنوان (سند الإقامة)، وصورة شخصية، واحجز موعداً إن كانت ولايتك تطلب ذلك عبر نظام مواعيد الهجرة. تأخّرك قد يؤثر على وصولك للخدمات الصحية والمدرسية والبنكية، لذا لا تؤجّل المراجعة. لأي رسم أو مهلة محددة تحقّق رسمياً من إدارة الهجرة في ولايتك لأنها قد تتغيّر.
التفاصيل: dalilarabtr.com/article/kimlik-renewal-expired$$, NULL, 'answered', true, '2026-07-06T10:00:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$هل تحديث العنوان إجباري للسوريين حاملي الحماية المؤقتة وماذا يحدث لو لم أحدّثه؟$$)::uuid, $$هل تحديث العنوان إجباري للسوريين حاملي الحماية المؤقتة وماذا يحدث لو لم أحدّثه؟$$, $$الكملك والحماية المؤقتة$$, $$نعم، تُلزم إدارة الهجرة السوريين تحت الحماية المؤقتة بتحديث عنوان السكن، وقد ترسل تنبيهات (غالباً عبر رسالة SMS بالتركية والعربية) تدعوك لتثبيت العنوان ضمن مهلة أو موعد محدّد. عدم التحديث ضمن المهلة قد يؤدي إلى تجميد وضعك القانوني (تجميد الحماية المؤقتة)، ما يجعل إقامتك غير نظامية ويحرمك من الحقوق والخدمات الرسمية كالرعاية الصحية في المستشفيات وتسجيل الأطفال في المدارس والمساعدات. يتم التحديث بحجز موعد عبر نظام مواعيد الهجرة (Göç Randevu) على randevu.goc.gov.tr أو بالاتصال بخط (157) أو بمراجعة إدارة الهجرة في ولايتك، واختيار خدمة تحديث المعلومات وتثبيت العنوان. ولأن المُهل والإجراءات قد تتغيّر، تحقّق رسمياً من إدارة الهجرة في ولايتك ولا تتجاهل أي رسالة تصلك.
التفاصيل: dalilarabtr.com/article/syrian-address-update-mandate-turkey$$, NULL, 'answered', false, '2026-07-04T00:24:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$هل يحتاج حامل الكملك إذن سفر (Yol İzin) للتنقّل بين الولايات؟$$)::uuid, $$هل يحتاج حامل الكملك إذن سفر (Yol İzin) للتنقّل بين الولايات؟$$, $$الكملك والحماية المؤقتة$$, $$حامل الكملك (الحماية المؤقتة) مقيّد بالولاية المسجّل فيها، وللسفر إلى ولاية أخرى يجب عادةً استخراج إذن سفر (Yol İzin Belgesi) من إدارة الهجرة في ولايتك، ويُطلب فيه بيان سبب السفر ضمن الأسباب المقبولة رسمياً مثل العمل أو الدراسة أو العلاج الصحي أو أسباب عائلية. يُمنح الإذن لمدة محددة قصيرة مرتبطة بغرض السفر، ويجب أن تلتزم بالوجهة والمدة المذكورتين فيه. يمكن تقديم الطلب حالياً عبر بوابة e-Devlet دون مراجعة الدائرة شخصياً. احتفظ بالإذن معك أثناء التنقّل لأنه قد يُطلب عند النقاط الأمنية أو من شركات النقل. ولأن الشروط قد تختلف حسب الولاية والسبب، تحقّق رسمياً من إدارة الهجرة قبل السفر.
التفاصيل: dalilarabtr.com/article/travel-permit$$, NULL, 'answered', false, '2026-07-01T14:48:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$هل يمكن تحويل الكملك (الحماية المؤقتة) إلى إقامة نظامية؟$$)::uuid, $$هل يمكن تحويل الكملك (الحماية المؤقتة) إلى إقامة نظامية؟$$, $$الكملك والحماية المؤقتة$$, $$نعم، يمكن في حالات معيّنة الانتقال من الكملك (الحماية المؤقتة) إلى إقامة نظامية مثل الإقامة العائلية أو الإقامة قصيرة الأمد، لكن ذلك ليس تلقائياً ويخضع لتقدير إدارة الهجرة وتوفّر شروط كل نوع إقامة. عادةً يتطلب الأمر تقديم ملف مستوفٍ للأوراق (جواز ساري، إثبات عنوان، تأمين صحي يغطّي مدة الإقامة، وسبب واضح للإقامة كالزواج أو الدراسة أو العقار حسب الحالة). مع ملاحظة مهمّة: بطاقة الحماية المؤقتة لا تمنح الحق بالانتقال إلى الإقامة الدائمة (طويلة الأمد)، ومدة بقائك بالكملك لا تُحتسب ضمن مدد الإقامة أو الجنسية. ننصح بشدّة بالتأكد من قبول ملفك من قبل إدارة الهجرة قبل إسقاط الكملك حتى لا تبقى بلا وضع نظامي أثناء الفترة الانتقالية. للتفاصيل والشروط المحدّثة تحقّق رسمياً من مديرية الهجرة (İl Göç İdaresi Müdürlüğü) في ولايتك.
التفاصيل: dalilarabtr.com/article/kimlik-to-residence$$, NULL, 'answered', false, '2026-06-29T05:12:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$كم الحد الأدنى للأجور في تركيا 2026؟ (الصافي والإجمالي)$$)::uuid, $$كم الحد الأدنى للأجور في تركيا 2026؟ (الصافي والإجمالي)$$, $$العمل والدخل$$, $$الحد الأدنى للأجور في تركيا لعام 2026 هو 28,075.50 ليرة صافي شهرياً (Net)، بينما الإجمالي قبل الاقتطاعات (Brüt) يبلغ 33,030 ليرة. الفرق بين الرقمين هو اقتطاعات حصة العامل: قسط الضمان الاجتماعي SGK بنسبة 14% وقسط التأمين ضد البطالة بنسبة 1%. تكلفة العامل على صاحب العمل تكون أعلى من الإجمالي لأنها تشمل أيضاً حصة صاحب العمل من أقساط SGK. هذه الأرقام رسمية لعام 2026 وتتغيّر سنوياً، لذا تحقّق رسمياً قبل أي حساب دقيق.
التفاصيل: dalilarabtr.com/article/asgari-ucret-turkiye-2026-net-brut-isveren-maliyeti$$, NULL, 'answered', true, '2026-06-26T19:36:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$هل يحتاج حامل الكملك (الحماية المؤقتة) إلى إذن عمل في تركيا؟$$)::uuid, $$هل يحتاج حامل الكملك (الحماية المؤقتة) إلى إذن عمل في تركيا؟$$, $$العمل وتصاريح العمل$$, $$حاملو الكملك (الحماية المؤقتة) يمكنهم العمل قانونياً بعد مرور ستة أشهر على الأقل على تاريخ منح وثيقة الحماية المؤقتة، ولديهم مساران بحسب نوع العمل. للعمل النظامي (في المصانع أو المتاجر أو المطاعم وسائر القطاعات) يتقدّم صاحب العمل بطلب إذن عمل (Çalışma İzni) عبر الأنظمة الرسمية (e-Devlet). أمّا نظام الإعفاء من إذن العمل، الذي يُستخرج بموجبه نموذج معلومات الإعفاء (Muafiyet Bilgi Formu)، فهو مخصّص للعمل الموسمي في الزراعة وتربية الحيوانات (mevsimlik tarım ve hayvancılık) ويُقدَّم طلبه لدى مديرية العمل في الولاية المسجَّل فيها الشخص. في الحالتين لا يعني ذلك العمل بلا تسجيل: يجب تسجيلك في الضمان الاجتماعي SGK لدى صاحب العمل. وقد تنطبق قيود إضافية (مثل نسبة العمالة الأجنبية في المنشأة، أو مهن تتطلّب موافقة مسبقة)، لذا تحقّق رسمياً من وضع مهنتك. التفاصيل: dalilarabtr.com/article/exemption-work-permit-full-guide-2026-06$$, NULL, 'answered', true, '2026-06-24T10:00:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$ما مخاطر العمل بدون تصريح (إذن عمل) في تركيا؟$$)::uuid, $$ما مخاطر العمل بدون تصريح (إذن عمل) في تركيا؟$$, $$العمل وتصاريح العمل$$, $$العمل بدون إذن عمل أو إعفاء يعرّضك أنت وصاحب العمل لغرامات إدارية، وقد يؤدي في حالتك كأجنبي إلى إجراءات تمسّ وضعك القانوني في تركيا. كما أنك تعمل بلا تأمين SGK، فتفقد التغطية الرسمية التي توثّق حقوقك (تسجيل إصابات العمل، احتساب مدة التقاعد، وسهولة إثبات علاقة العمل)، ويصبح المطالبة بحقوقك أصعب بكثير عند أي نزاع أو إصابة عمل، رغم أن العمل الفعلي قد يبقي لك بعض الحقوق أمام القضاء. البديل الآمن هو التسجيل النظامي عبر إذن العمل أو نموذج الإعفاء لحاملي الكملك مع تسجيلك في SGK. تحقّق رسمياً من متطلبات وضعك قبل بدء أي عمل.
التفاصيل: dalilarabtr.com/article/work-without-permit-risks-2025$$, NULL, 'answered', false, '2026-06-22T00:24:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$ما الفرق بين تأمين SGK 4A و Bağ-Kur 4B وأيهما يناسبني؟$$)::uuid, $$ما الفرق بين تأمين SGK 4A و Bağ-Kur 4B وأيهما يناسبني؟$$, $$العمل والتأمين$$, $$التصنيف 4A (SGK) هو نظام الضمان الاجتماعي للعامل الأجير الذي يعمل لدى صاحب عمل، حيث يتحمّل صاحب العمل تسجيلك ودفع الجزء الأكبر من الأقساط. أما 4B (Bağ-Kur) فهو نظام العاملين لحسابهم الخاص وأصحاب الشركات والمهن الحرة، وفيه تدفع أنت القسط كاملاً بنفسك. القاعدة العملية: إن كنت موظفاً براتب فأنت 4A، وإن كنت صاحب شركة أو تعمل مستقلاً فأنت 4B. كلا النظامين يمنحان تغطية صحية وتقاعدية، لكن قيمة القسط وطريقة الدفع تختلفان، لذا تحقّق رسمياً من قيمة قسطك حسب وضعك.
التفاصيل: dalilarabtr.com/article/sgk-4a-vs-bagkur-4b-foreigners-2026$$, NULL, 'answered', false, '2026-06-19T14:48:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$كم سنة تبقى نتيجة امتحان اليوس (YÖS) صالحة للتقديم على الجامعات التركية؟$$)::uuid, $$كم سنة تبقى نتيجة امتحان اليوس (YÖS) صالحة للتقديم على الجامعات التركية؟$$, $$التعليم$$, $$نتيجة امتحان اليوس (TR-YÖS) صالحة عادةً لمدة سنتين من تاريخ الامتحان، ويمكنك خلالها التقديم على الجامعات الحكومية والخاصة التي تعترف بها. لكل جامعة حدّها الأدنى الخاص من الدرجات وشروط قبولها، لذا راجع دليل القبول لكل جامعة تستهدفها. لأن بعض الجامعات تجري يوس خاصاً بها بشروط مختلفة، تحقّق رسمياً من مدة الصلاحية المعتمدة لدى الجامعة قبل الاعتماد على نتيجتك.
التفاصيل: dalilarabtr.com/article/yos-exam-guide$$, NULL, 'answered', false, '2026-06-17T05:12:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$كيف أعادل شهادتي الجامعية في تركيا عبر YÖK؟ وما هي نتائج المعادلة الممكنة؟$$)::uuid, $$كيف أعادل شهادتي الجامعية في تركيا عبر YÖK؟ وما هي نتائج المعادلة الممكنة؟$$, $$التعليم$$, $$تُقدَّم معادلة الشهادة الجامعية (YÖK Denklik) إلكترونياً عبر موقع مجلس التعليم العالي denklik.yok.gov.tr مع رفع الدبلوم وكشف العلامات مترجمَين ومصدَّقَين. تنتهي المعالجة إلى واحد من ثلاثة مسارات: معادلة كاملة (وثيقة الدنكلك)، أو طلب استكمال نواقص عبر امتحان تحديد المستوى (STS) أو دراسة مواد ناقصة، أو الرفض. تخصّصات مثل الطب وطب الأسنان والصيدلة والهندسة تتطلب غالباً اجتياز امتحان STS. تختلف المتطلبات والرسوم بحسب البلد والتخصص، لذا تحقّق رسمياً من قائمة الوثائق المحدَّثة عبر denklik.yok.gov.tr قبل التقديم.
التفاصيل: dalilarabtr.com/article/diploma-denklik-syrians-arabs-2026$$, NULL, 'answered', false, '2026-06-14T19:36:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$ماذا تغطّي المنحة التركية الحكومية (Türkiye Bursları) للطالب؟$$)::uuid, $$ماذا تغطّي المنحة التركية الحكومية (Türkiye Bursları) للطالب؟$$, $$التعليم$$, $$منحة الحكومة التركية (Türkiye Bursları) منحة كاملة تغطّي الرسوم الدراسية، وراتباً شهرياً، والسكن في مدينة جامعية، والتأمين الصحي، وتذكرة طيران ذهاباً وإياباً (عند القدوم لأول مرة وعند العودة إلى البلد بعد التخرّج)، وسنة مجانية لتعلّم اللغة التركية. يزداد الراتب الشهري بحسب المرحلة (بكالوريوس، ماجستير، دكتوراه)، وقيمة الراتب تُحدَّث سنوياً فلا تعتمد على رقم قديم وتحقّق رسمياً من الموقع turkiyeburslari.gov.tr. التقديم يكون إلكترونياً خلال فترة محددة تُعلَن كل عام.
التفاصيل: dalilarabtr.com/article/scholarship-turkiye-burslari$$, NULL, 'answered', false, '2026-06-12T10:00:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$هل يحق للطلاب السوريين والأجانب التسجيل في سكن الطلاب الحكومي KYK في تركيا؟$$)::uuid, $$هل يحق للطلاب السوريين والأجانب التسجيل في سكن الطلاب الحكومي KYK في تركيا؟$$, $$التعليم$$, $$نعم، يحقّ للطلاب الأجانب والسوريين المسجّلين في جامعة تركية والذين يدرسون على نفقتهم الخاصة التقديم على سكن الطلاب الحكومي (KYK Yurt) التابع للإدارة العامة للقروض والمساكن (KYGM) ضمن وزارة الشباب والرياضة (GSB). الشرط الحاسم للأجانب هو امتلاك رقم الهوية الأجنبية (رقم الكملك - Yabancı Kimlik Numarası)؛ فمن لا يملكه لا يستطيع التقديم إطلاقاً، لذا استخرجه مبكراً. يكون التقديم إلكترونياً عبر بوابة e-Devlet (turkiye.gov.tr) من خلال خدمة «طلب سكن للطلاب الدوليين» (Uluslararası Öğrenciler İçin Yurt Başvurusu)، خلال فترة تُعلَن قرب بداية العام الدراسي بعد صدور نتائج التوزيع الجامعي، وقد تُعلَن للطلاب الدوليين مواعيد تقديم إضافية (Ek Başvuru). السكن مدعوم ويشمل عادةً الإقامة مع وجبات (كثير من الوجبات مغطّى ببدل تغذية للمقيمين المسجّلين)، مقابل رسوم شهرية مدعومة إضافةً إلى مبلغ تأمين/وديعة (güvence bedeli) يُدفَع عند التسجيل. لأن الرسوم والمواعيد والأولويات وحصص الأسرّة تتغيّر كل عام، تحقّق رسمياً من الإعلان الرسمي وشروط الأهلية على موقع kygm.gsb.gov.tr وبوابة e-Devlet قبل التقديم.
التفاصيل: dalilarabtr.com/article/kyk-yurt-devlet-yabanci-suriyeli-ogrenciler-2026$$, NULL, 'answered', false, '2026-06-10T00:24:00.000Z', 'seed')
