INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$كيف أحجز موعد مشفى حكومي في تركيا عبر MHRS؟$$)::uuid, $$كيف أحجز موعد مشفى حكومي في تركيا عبر MHRS؟$$, $$الصحة$$, $$يمكنك حجز موعد في المشافي والمراكز الصحية الحكومية عبر نظام MHRS (Merkezi Hekim Randevu Sistemi) بثلاث طرق: تطبيق الجوال، موقع mhrs.gov.tr، أو الاتصال بخط ALO 182 المتاح على مدار الساعة. تحتاج إلى رقم هويتك (كملك/إقامة) المسجّل في النظام الصحي وعنوان محدّث لتظهر لك المشافي القريبة. للناطقين بالعربية يتوفّر دعم لغوي عبر خط 182 لمساعدتك في اختيار الطبيب والفرع والموعد. إذا لم تنجح في الحجز فغالباً بسبب مشكلة في تسجيل الرقم أو العنوان، ويُحلّ ذلك بمراجعة النظام أو الاتصال بـ182.
التفاصيل: dalilarabtr.com/article/mhrs-guide-syrians-arabs-2026$$, NULL, 'answered', true, '2026-06-07T14:48:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$ما هو تطبيق e-Nabız وكيف أدخل إلى سجلي الصحي في تركيا؟$$)::uuid, $$ما هو تطبيق e-Nabız وكيف أدخل إلى سجلي الصحي في تركيا؟$$, $$الصحة$$, $$e-Nabız هو السجل الصحي الإلكتروني الرسمي في تركيا (تابع لوزارة الصحة) الذي يجمع نتائج تحاليلك وصورك الشعاعية ووصفاتك الطبية ومواعيدك وتاريخك المرضي في مكان واحد. تدخل إليه عبر موقع enabiz.gov.tr أو التطبيق أو من خلال بوّابة الحكومة الإلكترونية (e-Devlet) باستخدام رقمك الوطني وكلمة المرور، ويمكنك التحكّم في مَن يطّلع على بياناتك (طبيب الأسرة فقط، أو الطبيب المعالج، أو منح صلاحية مؤقتة). الخدمة متاحة للأجانب الحاملين لإقامة سارية ورقم أجنبي (Yabancı Kimlik Numarası) والمسجّلين في e-Devlet، وتساعدك على متابعة أدويتك ونتائجك دون الحاجة لمراجعة المشفى في كل مرة. للتأكّد من أحدث خطوات الدخول، راجع الموقع الرسمي.
التفاصيل: dalilarabtr.com/article/e-nabiz-electronic-health-record-2026$$, NULL, 'answered', false, '2026-06-05T05:12:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$كيف أستخرج الرقم الضريبي (Vergi Numarası) للأجانب أونلاين مجاناً؟$$)::uuid, $$كيف أستخرج الرقم الضريبي (Vergi Numarası) للأجانب أونلاين مجاناً؟$$, $$معاملات رسمية$$, $$يمكن للأجانب استخراج الرقم الضريبي (Vergi Numarası) مجاناً وأونلاين دون مراجعة دائرة الضرائب، عبر موقع الدائرة الضريبية الرقمية ivd.gib.gov.tr (dijital.gib.gov.tr) واختيار خدمة «الرقم الضريبي المحتمل للأجانب». تملأ النموذج ببياناتك كما في جواز السفر وترفع صورة صفحة الصورة من الجواز، فيظهر لك الرقم فوراً. هذا الرقم ضروري لفتح حساب بنكي ودفع الفواتير والمعاملات الرسمية. إذا كنت مسجّلاً في e-Devlet فيمكنك أيضاً الاستعلام عن رقمك من هناك.
التفاصيل: dalilarabtr.com/article/vergi-numarasi-tax-number-foreigners$$, NULL, 'answered', true, '2026-06-02T19:36:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;

INSERT INTO questions (id, question, category, answer, asker_name, status, is_featured, answered_at, ip_hash)
VALUES (md5($$كيف أسجّل المولود الجديد في تركيا وأستخرج شهادة الميلاد؟$$)::uuid, $$كيف أسجّل المولود الجديد في تركيا وأستخرج شهادة الميلاد؟$$, $$معاملات رسمية$$, $$عند ولادة طفلك في تركيا يصدر المشفى تقرير ولادة (Doğum Raporu)، ثم تُسجّل الولادة رسمياً في مديرية النفوس (Nüfus Müdürlüğü) لاستخراج شهادة/وثيقة الميلاد (Doğum Belgesi) وقيد الطفل. يُنصح بإتمام التسجيل خلال المهلة النظامية بعد الولادة لتجنّب الغرامة وأي تعقيدات (تحقّق رسمياً من المهلة المحدّثة لدى دائرتك). ويمكن لاحقاً الاستعلام أو المتابعة عبر e-Devlet حسب المتاح. بعد التسجيل في النفوس، تُبلّغ إدارة الهجرة (Göç İdaresi) في ولاية إقامتك ليُضاف المولود إلى وضعك (كملك/إقامة) وتُصدر له وثيقة الحماية/الإقامة الخاصة به، وقد تحتاج لاحقاً لمراجعة القنصلية لاستخراج وثائق بلدك للطفل. تحقّق رسمياً من المهلة والأوراق المطلوبة في دائرتك. التفاصيل: dalilarabtr.com/article/newborn-birth-registration-turkey$$, NULL, 'answered', false, '2026-05-31T10:00:00.000Z', 'seed')
ON CONFLICT (id) DO NOTHING;
